package com.example.editor.project;

import java.util.List;

/** Puerto neutral del almacenamiento de proyectos, reutilizable por MongoDB o un cliente de escritorio. */
public interface ProjectStoragePort {
    /** Descripción: Crea o prepara el resultado de «create» dentro de ProjectStoragePort. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSession create(CreateLocalProjectRequest request);
    /** Descripción: Crea o prepara el resultado de «open» dentro de ProjectStoragePort. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSession open(OpenLocalProjectRequest request);
    /** Descripción: Ejecuta la operación «session» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSession session();
    /** Descripción: Ejecuta la operación «recentProjects» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ List<ProjectSummary> recentProjects();
    /** Descripción: Elimina o libera el recurso gestionado por «close» de forma controlada. Entradas: no requiere parámetros de entrada. Salida: no devuelve valor; completa la operación o comunica el fallo mediante el contrato existente. */ void close();
    /** Descripción: Ejecuta la operación «tree» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: view: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectTreeNode tree(ProjectTreeView view);
    /** Descripción: Obtiene la información correspondiente a «read» dentro de ProjectStoragePort. Entradas: relativePath: ruta o ubicación utilizada por la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectFileContent read(String relativePath);
    /** Descripción: Actualiza el estado gestionado por ProjectStoragePort mediante la operación «write». Entradas: relativePath: ruta o ubicación utilizada por la operación; request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectOperationResult write(String relativePath,ProjectFileWriteRequest request);
    /** Descripción: Crea o prepara el resultado de «createEntry» dentro de ProjectStoragePort. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectOperationResult createEntry(ProjectEntryCreateRequest request);
    /** Descripción: Ejecuta la operación «move» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectOperationResult move(ProjectMoveRequest request);
    /** Descripción: Ejecuta la operación «duplicate» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectOperationResult duplicate(ProjectDuplicateRequest request);
    /** Descripción: Elimina o libera el recurso gestionado por «delete» de forma controlada. Entradas: relativePath: ruta o ubicación utilizada por la operación; expectedEtag: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectOperationResult delete(String relativePath,String expectedEtag);
    /** Descripción: Ejecuta la operación «upload» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: directory: ruta o ubicación utilizada por la operación; fileName: archivo o contenido que debe procesarse; content: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ ProjectOperationResult upload(String directory,String fileName,byte[] content);
    /** Descripción: Ejecuta la operación «download» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: relativePath: ruta o ubicación utilizada por la operación. Salida: devuelve el resultado definido por el contrato del método. */ byte[] download(String relativePath);
    /** Descripción: Ejecuta la operación «exportArchive» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ byte[] exportArchive();
    /** Descripción: Ejecuta la operación «importArchive» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: parentDirectory: dato de entrada necesario para la operación; projectName: dato de entrada necesario para la operación; content: valor de entrada que debe procesarse. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSession importArchive(String parentDirectory,String projectName,byte[] content);
    /** Descripción: Ejecuta la operación «importDirectory» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSession importDirectory(ImportLocalProjectDirectoryRequest request);
    /** Descripción: Ejecuta la operación «pollChanges» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: no requiere parámetros de entrada. Salida: devuelve el resultado definido por el contrato del método. */ ProjectChangeSet pollChanges();
    /** Descripción: Ejecuta la operación «previewSynchronization» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSynchronizationPlan previewSynchronization(ProjectSyncRequest request);
    /** Descripción: Actualiza el estado gestionado por ProjectStoragePort mediante la operación «synchronize». Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSynchronizationResult synchronize(ProjectSyncRequest request);
    /** Descripción: Actualiza el estado gestionado por ProjectStoragePort mediante la operación «saveTabs». Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSession saveTabs(ProjectTabSessionRequest request);
    /** Descripción: Obtiene la información correspondiente a «search» dentro de ProjectStoragePort. Entradas: query: dato de entrada necesario para la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSearchResult search(String query);
    /** Actualiza capacidades, modo de experiencia y artefacto principal del proyecto activo. */ /** Descripción: Ejecuta la operación «configure» correspondiente a la responsabilidad de ProjectStoragePort. Entradas: request: solicitud con los datos necesarios para ejecutar la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectSession configure(ProjectConfigurationRequest request);
    /** Descripción: Obtiene la información correspondiente a «resolvePath» dentro de ProjectStoragePort. Entradas: relativePath: ruta o ubicación utilizada por la operación. Salida: devuelve el resultado definido por el contrato del método. */ ProjectResolvedPath resolvePath(String relativePath);
}
